package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)

	var hpY, atkY, defY int
	var hpM, atkM, defM int
	var h, a, d int

	fmt.Fscan(reader, &hpY, &atkY, &defY)
	fmt.Fscan(reader, &hpM, &atkM, &defM)
	fmt.Fscan(reader, &h, &a, &d)

	minCost := 1 << 30

	maxAddATK := 100 + defM + 5
	maxAddDEF := atkM + 5

	for addATK := 0; addATK <= maxAddATK; addATK++ {
		dmgToMonster := atkY + addATK - defM
		if dmgToMonster <= 0 {
			continue
		}
		// time to kill monster
		turns := (hpM + dmgToMonster - 1) / dmgToMonster

		for addDEF := 0; addDEF <= maxAddDEF; addDEF++ {
			dmgToYang := atkM - (defY + addDEF)
			if dmgToYang < 0 {
				dmgToYang = 0
			}

			totalDamageTaken := turns * dmgToYang
			needHP := totalDamageTaken - hpY + 1
			if needHP < 0 {
				needHP = 0
			}

			cost := addATK*a + addDEF*d + needHP*h
			if cost < minCost {
				minCost = cost
			}
		}
	}

	fmt.Println(minCost)
}
